CREATE TABLE users (id uuid PRIMARY KEY, username text UNIQUE NOT NULL, display_name text NOT NULL, country text NOT NULL DEFAULT 'ES', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','banned','deleted')), role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','support','moderator','admin')), over18 boolean NOT NULL DEFAULT false, age_status text NOT NULL DEFAULT 'declared', trust text NOT NULL DEFAULT 'basic', is_demo boolean NOT NULL DEFAULT false, onboarding boolean NOT NULL DEFAULT true, created_at bigint NOT NULL, updated_at bigint NOT NULL);
CREATE SCHEMA IF NOT EXISTS identity;
CREATE TABLE identity.contacts (user_id uuid PRIMARY KEY REFERENCES users(id), email text UNIQUE NOT NULL, birth_date text, provider text NOT NULL DEFAULT 'email', provider_sub text, phone_verified boolean NOT NULL DEFAULT false, UNIQUE(provider,provider_sub));
CREATE TABLE age_verifications (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL, over18 boolean NOT NULL, assurance text NOT NULL, reference text, expires_at bigint NOT NULL, created_at bigint NOT NULL);
CREATE TABLE preferences (user_id uuid PRIMARY KEY REFERENCES users(id), data jsonb NOT NULL);
CREATE TABLE reliability_profiles (user_id uuid PRIMARY KEY REFERENCES users(id), accepted integer NOT NULL DEFAULT 0, attended integer NOT NULL DEFAULT 0, late_cancels integer NOT NULL DEFAULT 0);
CREATE TABLE sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), access_hash text UNIQUE NOT NULL, refresh_hash text UNIQUE NOT NULL, family uuid NOT NULL, access_expires bigint NOT NULL, expires_at bigint NOT NULL, revoked boolean NOT NULL DEFAULT false, device_name text NOT NULL, created_at bigint NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE auth_challenges (id uuid PRIMARY KEY, email text NOT NULL, code_hash text NOT NULL, binding_hash text NOT NULL, attempts integer NOT NULL DEFAULT 0, expires_at bigint NOT NULL, used boolean NOT NULL DEFAULT false, data jsonb NOT NULL);
CREATE TABLE communities (id uuid PRIMARY KEY, name text NOT NULL, kind text NOT NULL, city text NOT NULL, description text NOT NULL, method text NOT NULL CHECK(method IN ('code','domain','approval')), code_hash text, domain text, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE memberships (user_id uuid REFERENCES users(id), community_id uuid REFERENCES communities(id), verified boolean NOT NULL DEFAULT false, created_at bigint NOT NULL, PRIMARY KEY(user_id,community_id));
CREATE INDEX memberships_community ON memberships(community_id,verified);
CREATE TABLE friendships (a uuid REFERENCES users(id), b uuid REFERENCES users(id), status text NOT NULL CHECK(status IN ('pending','accepted')), created_at bigint NOT NULL, PRIMARY KEY(a,b), CHECK(a<>b));
CREATE TABLE invitations (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), token_hash text UNIQUE NOT NULL, expires_at bigint NOT NULL, used_by uuid REFERENCES users(id));
CREATE TABLE activities (id text PRIMARY KEY, label text NOT NULL, emoji text NOT NULL, family text NOT NULL, compatible jsonb NOT NULL, enabled boolean NOT NULL DEFAULT true, min_minutes integer NOT NULL DEFAULT 20);
CREATE TABLE intents (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), activity text NOT NULL REFERENCES activities(id), start_at bigint NOT NULL, end_at bigint NOT NULL, expires_at bigint NOT NULL, radius integer NOT NULL CHECK(radius BETWEEN 1000 AND 5000), visibility text NOT NULL CHECK(visibility IN ('friends','fof','community','open')), community_id uuid REFERENCES communities(id), status text NOT NULL CHECK(status IN ('SEARCHING','RESERVED','MATCHED','CANCELLED','EXPIRED')), lat double precision, lon double precision, cell_x integer, cell_y integer, budget integer NOT NULL DEFAULT 1, accessible boolean NOT NULL DEFAULT false, notify_liquidity boolean NOT NULL DEFAULT false, retry_after bigint NOT NULL DEFAULT 0, created_at bigint NOT NULL);
CREATE UNIQUE INDEX one_live_intent ON intents(user_id) WHERE status IN ('SEARCHING','RESERVED');
CREATE INDEX intents_retrieval ON intents(status,cell_x,cell_y,expires_at);
CREATE INDEX intents_expiry ON intents(expires_at) WHERE status IN ('SEARCHING','RESERVED');
CREATE TABLE venues (id uuid PRIMARY KEY, name text NOT NULL, address text NOT NULL, lat double precision NOT NULL, lon double precision NOT NULL, category text NOT NULL, activities jsonb NOT NULL, public boolean NOT NULL DEFAULT true, safe boolean NOT NULL DEFAULT false, accessible boolean NOT NULL DEFAULT true, capacity integer NOT NULL DEFAULT 6, budget integer NOT NULL DEFAULT 1, rating double precision NOT NULL DEFAULT 4, open_hour integer NOT NULL DEFAULT 0, close_hour integer NOT NULL DEFAULT 0, timezone text NOT NULL DEFAULT 'Europe/Madrid', is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE matches (id uuid PRIMARY KEY, activity text NOT NULL REFERENCES activities(id), venue_id uuid REFERENCES venues(id), fallback_venues jsonb NOT NULL DEFAULT '[]', state text NOT NULL, scheduled_at bigint NOT NULL, ends_at bigint NOT NULL, expires_at bigint NOT NULL, created_at bigint NOT NULL, confirmed_at bigint, is_demo boolean NOT NULL DEFAULT false, explanation jsonb NOT NULL DEFAULT '{}');
CREATE INDEX matches_pending ON matches(state,expires_at);
CREATE TABLE match_members (match_id uuid REFERENCES matches(id), user_id uuid REFERENCES users(id), intent_id uuid REFERENCES intents(id), response text NOT NULL DEFAULT 'pending', distance_band text NOT NULL DEFAULT '~1 km', checked_in boolean NOT NULL DEFAULT false, checked_at bigint, checkin_method text, safety_exit boolean NOT NULL DEFAULT false, feedback jsonb, PRIMARY KEY(match_id,user_id));
CREATE INDEX member_user ON match_members(user_id);
CREATE TABLE attendance (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), match_id uuid REFERENCES matches(id), method text NOT NULL, created_at bigint NOT NULL, UNIQUE(user_id,match_id));
CREATE TABLE reliability_events (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), match_id uuid REFERENCES matches(id), kind text NOT NULL, created_at bigint NOT NULL, UNIQUE(user_id,match_id,kind));
CREATE TABLE blocks (blocker uuid REFERENCES users(id), blocked uuid REFERENCES users(id), created_at bigint NOT NULL, PRIMARY KEY(blocker,blocked), CHECK(blocker<>blocked));
CREATE INDEX blocks_reverse ON blocks(blocked,blocker);
CREATE TABLE messages (id uuid PRIMARY KEY, match_id uuid REFERENCES matches(id), sender_id uuid REFERENCES users(id), body text NOT NULL, state text NOT NULL DEFAULT 'visible', created_at bigint NOT NULL, expires_at bigint NOT NULL);
CREATE INDEX messages_match ON messages(match_id,created_at);
CREATE TABLE reports (id uuid PRIMARY KEY, reporter uuid REFERENCES users(id), subject uuid REFERENCES users(id), match_id uuid REFERENCES matches(id), message_id uuid REFERENCES messages(id) ON DELETE SET NULL, category text NOT NULL, details text NOT NULL, severity integer NOT NULL, state text NOT NULL DEFAULT 'open', created_at bigint NOT NULL, resolved_at bigint);
CREATE INDEX report_queue ON reports(state,severity,created_at);
CREATE TABLE moderation_cases (id uuid PRIMARY KEY, report_id uuid REFERENCES reports(id), subject uuid REFERENCES users(id), actor uuid REFERENCES users(id), action text NOT NULL, rationale text NOT NULL, created_at bigint NOT NULL, expires_at bigint);
CREATE TABLE appeals (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), case_id uuid REFERENCES moderation_cases(id), reason text NOT NULL, state text NOT NULL DEFAULT 'open', decision text, created_at bigint NOT NULL);
CREATE TABLE notifications (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), kind text NOT NULL, title text NOT NULL, body text NOT NULL, read boolean NOT NULL DEFAULT false, created_at bigint NOT NULL, delivered_at bigint, attempts integer NOT NULL DEFAULT 0, expires_at bigint NOT NULL);
CREATE INDEX notifications_delivery ON notifications(delivered_at,expires_at);
CREATE TABLE devices (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), platform text NOT NULL, push_token text NOT NULL UNIQUE, created_at bigint NOT NULL);
CREATE TABLE consents (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), purpose text NOT NULL, granted boolean NOT NULL, version text NOT NULL, created_at bigint NOT NULL);
CREATE TABLE audit_events (id uuid PRIMARY KEY, actor uuid, action text NOT NULL, subject uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at bigint NOT NULL);
CREATE TABLE analytics_events (id uuid PRIMARY KEY, name text NOT NULL, activity text, community_id uuid, city text, value double precision NOT NULL DEFAULT 1, created_at bigint NOT NULL);
CREATE INDEX analytics_rollup ON analytics_events(name,created_at,community_id,activity);
CREATE TABLE feature_flags (key text PRIMARY KEY, enabled boolean NOT NULL, description text NOT NULL);
CREATE TABLE idempotency (user_id uuid REFERENCES users(id), key text NOT NULL, scope text NOT NULL, hash text NOT NULL, result jsonb NOT NULL, expires_at bigint NOT NULL, PRIMARY KEY(user_id,key,scope));
CREATE TABLE rate_buckets (key text PRIMARY KEY, hits integer NOT NULL, resets_at bigint NOT NULL);
